sql.if:
AND EXISTS (SELECT 1 FROM finance_receivable_item ri WHERE ri.receivable_id=r.id AND ri.deleted=FALSE)
AND NOT EXISTS (
    SELECT 1 FROM finance_receivable_item ri
    LEFT JOIN inventory_outbound_item oi ON ri.source_type='INVENTORY_OUTBOUND_ITEM' AND oi.id=ri.source_id AND oi.deleted=FALSE
    LEFT JOIN inventory_outbound ib ON ib.id=oi.outbound_id AND ib.deleted=FALSE
    WHERE ri.receivable_id=r.id AND ri.deleted=FALSE AND (
        ib.warehouse_id IS NULL
        OR ib.warehouse_id <> #{query.warehouseId}


            OR ib.warehouse_id NOT IN
                #{id}

            OR TRUE

    )
)

mapper.sql:
WITH accounts AS (
SELECT 'RECEIVABLE' AS account_type, r.id AS document_id, r.receivable_no AS document_no, r.order_id AS source_id, so.order_no AS source_no, r.customer_id AS counterparty_id, r.customer_name_snapshot AS counterparty_name, r.settlement_customer_id, r.settlement_customer_name_snapshot AS settlement_customer_name, r.event_at, r.due_date, r.amount, COALESCE(red.amount,0) AS red_amount, r.amount - COALESCE(red.amount,0) AS net_amount, COALESCE(wo.amount,0) AS written_off_amount, GREATEST(r.amount - COALESCE(red.amount,0) - COALESCE(wo.amount,0),0) AS open_amount FROM finance_receivable r JOIN sales_order so ON so.id=r.order_id AND so.deleted=FALSE JOIN customer c ON c.id=r.customer_id AND c.deleted=FALSE LEFT JOIN LATERAL (SELECT SUM(x.amount) AS amount FROM finance_receivable x WHERE x.original_receivable_id=r.id AND x.entry_type='RED' AND x.deleted=FALSE AND x.event_at < #{endAt}) red ON TRUE LEFT JOIN LATERAL (SELECT SUM(CASE WHEN x.entry_type='NORMAL' THEN x.amount ELSE -x.amount END) AS amount FROM finance_write_off x WHERE x.target_type='RECEIVABLE' AND x.target_id=r.id AND x.deleted=FALSE AND x.written_off_at < #{endAt}) wo ON TRUE WHERE r.entry_type='NORMAL' AND r.deleted=FALSE AND r.event_at < #{endAt}
SELECT 'PAYABLE' AS account_type, p.id AS document_id, p.payable_no AS document_no, p.purchase_order_id AS source_id, po.order_no AS source_no, p.supplier_id AS counterparty_id, p.supplier_name_snapshot AS counterparty_name, NULL::bigint AS settlement_customer_id, NULL::varchar AS settlement_customer_name, p.event_at, p.due_date, p.amount, COALESCE(red.amount,0) AS red_amount, p.amount - COALESCE(red.amount,0) AS net_amount, COALESCE(wo.amount,0) AS written_off_amount, GREATEST(p.amount - COALESCE(red.amount,0) - COALESCE(wo.amount,0),0) AS open_amount FROM finance_payable p JOIN purchase_order po ON po.id=p.purchase_order_id AND po.deleted=FALSE LEFT JOIN LATERAL (SELECT SUM(x.amount) AS amount FROM finance_payable x WHERE x.original_payable_id=p.id AND x.entry_type='RED' AND x.deleted=FALSE AND x.event_at < #{endAt}) red ON TRUE LEFT JOIN LATERAL (SELECT SUM(CASE WHEN x.entry_type='NORMAL' THEN x.amount ELSE -x.amount END) AS amount FROM finance_write_off x WHERE x.target_type='PAYABLE' AND x.target_id=p.id AND x.deleted=FALSE AND x.written_off_at < #{endAt}) wo ON TRUE WHERE p.entry_type='NORMAL' AND p.deleted=FALSE AND p.event_at < #{endAt}
), aged AS ( SELECT accounts.*, CASE WHEN due_date IS NULL THEN NULL ELSE GREATEST(#{query.asOfDate}::date-due_date,0) END AS overdue_days, CASE WHEN due_date IS NULL THEN 'UNKNOWN' WHEN due_date >= #{query.asOfDate}::date THEN 'NOT_DUE' WHEN #{query.asOfDate}::date-due_date <= 30 THEN 'DAYS_1_30' WHEN #{query.asOfDate}::date-due_date <= 60 THEN 'DAYS_31_60' WHEN #{query.asOfDate}::date-due_date <= 90 THEN 'DAYS_61_90' WHEN #{query.asOfDate}::date-due_date <= 180 THEN 'DAYS_91_180' ELSE 'OVER_180' END AS aging_bucket FROM accounts WHERE open_amount > 0 )
